// 全角/半角：按字宽推进光标，避免英文被拉散
static inline uint8_t zhGlyphWidth(uint32_t cp) {
  for (int i = 0; i < ZH_COUNT; i++) {
    if (pgm_read_dword(&ZH_GLYPHS[i].cp) == cp) {
      return pgm_read_byte(&ZH_GLYPHS[i].w);
    }
  }
  return ZH_CELL_W;
}
